import{_ as r,l as n,o as e,c as o,v as i,p as d,x as t,d as s,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"FIM 训练目标","description":"","frontmatter":{"title":"FIM 训练目标","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fim-training.md","filePath":"llm/fim-training.md","lastUpdated":1789023840000}'),m={name:"llm/fim-training.md"};function f(c,a,E,_,u,M){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="fim-训练目标" tabindex="-1">FIM 训练目标 <a class="header-anchor" href="#fim-训练目标" aria-label="Permalink to &quot;FIM 训练目标&quot;">​</a></h1><div class="epigraph"><p>把一段文本的中间挖掉，放到后缀之后再预测，模型就能在已知左右上下文时填空，而不必只从左写到右。</p><footer>—— Bavarian et al., Efficient Training of Language Models to Fill in the Middle, 2022</footer></div><p><a href="/llm/repo-level-code-data">上一课</a>让相关文件出现在同一窗口。目标仍是标准的下一 token：总是预测最右端。编辑器里的补全却常常是「光标在函数中间，上面有签名、下面有调用」。本课不重讲仓库抽样。缺口是训练目标：Bavarian 等人的 Fill-in-the-Middle（FIM）用特殊哨兵把「前缀、后缀、中间」重排成仍可用因果 LM 训练的一条序列。后课长文档上采样改长度分布；本课改条件方向。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>因果语言模型天然适配「写到文件末尾」。对代码与文档编辑，缺失的是中间。若只靠指令微调教 FIM，预训练表征从未见过「后缀先于中间」的条件，样本效率差。需要在预训练里以一定概率把文档改写成 FIM 格式，且切分必须用已经冻结的 <a href="/llm/special-tokens">特殊 token</a>：前缀、中间、后缀哨兵不能与内容 BPE 冲突。</p><p>Bavarian 等人表明，合理的 FIM 比例下，从左到右的能力不必崩。工程缺口是比例、跨度分布、以及与仓库级打包是否同屏做 FIM（在超文档上挖一段，还是只在单文件内挖）。</p><h3 id="哨兵是协议-不是注释字符串" tabindex="-1">哨兵是协议，不是注释字符串 <a class="header-anchor" href="#哨兵是协议-不是注释字符串" aria-label="Permalink to &quot;哨兵是协议，不是注释字符串&quot;">​</a></h3><p>若用可读的 <code>&lt;fim_prefix&gt;</code> 而预分词没有先抽出，BPE 会把它切碎，训练与推理对不齐。FIM 符号应在词表扩展的协议区占位，预训练就要插入，以免嵌入成为 glitch。InCoder（Fried 等人）用另一套跨度填空；本课以因果 LM 上的重排 FIM 为主，不把编码器去噪整段搬回来。</p><p><span class="marginnote">数字逐位切分后，挖中间跨度应按 token 或按字符声明清楚。按字符挖再切分，边界可能落在数位中间，这其实无害，但日志里不要把它当成「切词 bug」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>以概率 \\(p_{\\mathrm{FIM}}\\) 选择文档（或仓库超文档中的一个文件）。均匀或按长度偏置地采样两点，把序列分成 prefix、middle、suffix。输出排列为 prefix + 后缀哨兵 + suffix + 中间哨兵 + middle，或论文中的其他等价排列；损失仍只在需要预测的位置上计（通常预测 middle，有时也训其他段）。\\(p_{\\mathrm{FIM}}\\) 过低，编辑任务弱；过高，普通续写掉点。Bavarian 等人给出可参考的中等比例，落地时用代码探针与普通 perplexity 一起盯。</p><p>仓库级数据上，优先在单文件内 FIM，避免挖出来的 middle 落在两个无关文件的拼接缝上——那种「中间」没有编辑语义。跨文件 FIM 只有在排布已经保证强相关时才值得开。</p><h3 id="推理格式必须与训练同一排列" tabindex="-1">推理格式必须与训练同一排列 <a class="header-anchor" href="#推理格式必须与训练同一排列" aria-label="Permalink to &quot;推理格式必须与训练同一排列&quot;">​</a></h3><p>补全 API 若改哨兵顺序，等于换任务。把排列写进词表卡片，与聊天模板并列。约束解码可以禁止在 middle 段之前结束，但那是推理课；预训练只要保证哨兵可学。</p><p><span class="marginnote">FIM 会改变有效长度：同样窗口，重排后注意力看到的「时间顺序」与源文件行号不同。长依赖评测应区分普通续写与填空两套。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重排并不打破因果掩码：模型仍然只能看左边。它改变的是左边包含什么——填空时左边既有真正的前文，也有物理上靠后的后缀。于是中间 token 的预测能条件到双向的源文本信息，尽管计算图仍是单向的。这是数据变换，不是把 SDPA 改成双向。</p>',17)),(e(),d(h,null,{default:t(()=>[p(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E6%96%87%E6%A1%A3%20token%22%5D%20--%3E%20CUT%5B%22%E5%88%87%E6%88%90%E5%89%8D%E7%BC%80%20%2F%20%E4%B8%AD%E9%97%B4%20%2F%20%E5%90%8E%E7%BC%80%22%5D%0A%20%20CUT%20--%3E%20ARR%5B%22%E5%93%A8%E5%85%B5%E9%87%8D%E6%8E%92%E6%88%90%E5%9B%A0%E6%9E%9C%E5%BA%8F%E5%88%97%22%5D%0A%20%20ARR%20--%3E%20LM%5B%22%E6%A0%87%E5%87%86%E4%B8%8B%E4%B8%80%20token%20%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>FIM 不是通用双向编码器，不能替代 T5 式跨度去噪的全部评测。对自然语言长篇，乱挖中间可能切断指代，收益小于代码。它也不增加真正的上下文长度——窗口仍满则仍截断。下一课处理的是：长文档在混合物里太少，模型在预训练里很少见到接近窗口上限的连贯文本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲仓库抽样；只补因果 LM 上的中间填空目标。</li><li>用协议哨兵重排 prefix/suffix/middle，预训练就要插入，避免 glitch。</li><li>比例与挖空范围要同时盯续写与编辑探针；优先单文件内挖空。</li><li>仍是单向注意力，双向来自数据布局。</li><li>出处：Bavarian et al., 2022；Fried et al., InCoder, 2022。</li></ul>',4))])}const I=r(m,[["render",f]]);export{F as __pageData,I as default};
